package com.bank.streams;

import java.math.BigDecimal;

// A record is a compact immutable data carrier for one trade slip.
public record Trade(String tradeId, String accountId, String symbol,
                    int quantity, BigDecimal price, String side) {
    public BigDecimal amount() { return price.multiply(BigDecimal.valueOf(quantity)); }
}
