package com.bank.streams;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.*;
import static java.util.stream.Collectors.*;

public class TradeReports {
    private static final Logger log = Logger.getLogger(TradeReports.class.getName());

    // Rajesh owns SAV2001, Priya owns CUR3001.
    static final List<Trade> trades = List.of(
        new Trade("T1", "SAV2001", "RELIANCE", 100, new BigDecimal("2450"), "BUY"),
        new Trade("T2", "SAV2001", "TCS",       50, new BigDecimal("3520"), "BUY"),
        new Trade("T3", "CUR3001", "RELIANCE", 200, new BigDecimal("2450"), "SELL"),
        new Trade("T4", "SAV2001", "HDFC",     150, new BigDecimal("1650"), "BUY"),
        new Trade("T5", "CUR3001", "TCS",       75, new BigDecimal("3520"), "BUY")
    );

    public static void main(String[] args) {
        // Group trades by account: Map<accountId, List<Trade>>
        Map<String, List<Trade>> byAccount =
            trades.stream().collect(groupingBy(Trade::accountId));
        log.info(() -> "Trades by account: " + byAccount.keySet());

        // Count trades per symbol: Map<symbol, Long>
        Map<String, Long> countBySymbol =
            trades.stream().collect(groupingBy(Trade::symbol, counting()));
        log.info(() -> "Count by symbol: " + countBySymbol);

        // Total traded amount per account (BigDecimal-safe reduction)
        Map<String, BigDecimal> totalByAccount = trades.stream()
            .collect(groupingBy(Trade::accountId,
                reducing(BigDecimal.ZERO, Trade::amount, BigDecimal::add)));
        log.info(() -> "Total amount by account: " + totalByAccount);

        // Top 3 trades by amount (descending sort + limit)
        List<Trade> top3 = trades.stream()
            .sorted(Comparator.comparing(Trade::amount).reversed())
            .limit(3).toList();
        log.info(() -> "Top 3 by amount: "
            + top3.stream().map(Trade::tradeId).collect(joining(", ")));

        // Partition BUY vs SELL: Map<Boolean, List<Trade>>
        Map<Boolean, List<Trade>> buyVsSell = trades.stream()
            .collect(partitioningBy(t -> "BUY".equals(t.side())));
        log.info(() -> "BUY count: " + buyVsSell.get(true).size()
                     + ", SELL count: " + buyVsSell.get(false).size());

        // Average price per symbol (double is fine for display, not for money math)
        Map<String, Double> avgPrice = trades.stream()
            .collect(groupingBy(Trade::symbol,
                averagingDouble(t -> t.price().doubleValue())));
        log.info(() -> "Average price by symbol: " + avgPrice);

        // Distinct symbols, sorted
        List<String> symbols = trades.stream()
            .map(Trade::symbol).distinct().sorted().toList();
        log.info(() -> "Distinct symbols: " + symbols);

        // Comma-separated trade IDs
        String tradeIds = trades.stream().map(Trade::tradeId).collect(joining(", "));
        log.info(() -> "All trade IDs: " + tradeIds);
    }
}
